import numpy as np
import pandas as pd
from datetime import datetime, date, timedelta
import zoneinfo
from dateutil.relativedelta import relativedelta
import re

def r_time_add(time, periods=None, year=None, month=None, week=None, 
               day=None, hour=None, minute=None, second=None, 
               roll_month="preday", roll_dst="post", *args, **kwargs):

    # Handle ... (dots)
    formal_params = {'year', 'month', 'week', 'day', 'hour', 'minute', 'second', 'roll_month', 'roll_dst'}
    dots = {k: v for k, v in kwargs.items() if k not in formal_params}
    for k in list(dots.keys()):
        new_k = re.sub(r's$', '', k)
        dots[new_k] = dots.pop(k)

    if periods is None:
        periods_dict = {}
    elif isinstance(periods, dict):
        periods_dict = periods.copy()
    else:
        raise TypeError("character periods are not implemented yet")

    for k, v in dots.items():
        periods_dict[k] = v

    prds = {'year': year, 'month': month, 'week': week, 'day': day, 
            'hour': hour, 'minute': minute, 'second': second}

    for nm, val in prds.items():
        if val is not None:
            if nm not in periods_dict or periods_dict[nm] is None:
                periods_dict[nm] = val
            else:
                periods_dict[nm] = periods_dict[nm] + val

    periods_dict = {k: v for k, v in periods_dict.items() if v is not None}

    if time is None:
        return None

    t_series = pd.Series(time)
    if len(t_series) == 0:
        return time

    tz_name = "UTC"
    first_val = t_series.iloc[0]
    if hasattr(first_val, 'tzinfo') and first_val.tzinfo is not None:
        tz_name = str(first_val.tzinfo)
    elif isinstance(first_val, pd.Timestamp) and first_val.tz is not None:
        tz_name = str(first_val.tz)

    try:
        tz = zoneinfo.ZoneInfo(tz_name)
    except Exception:
        tz = zoneinfo.ZoneInfo("UTC")

    def get_vec(name):
        val = periods_dict.get(name, 0)
        if isinstance(val, (list, np.ndarray, pd.Series)):
            return np.array(val)
        return np.array([val])

    v_year = get_vec('year')
    v_month = get_vec('month')
    v_week = get_vec('week')
    v_day = get_vec('day')
    v_hour = get_vec('hour')
    v_minute = get_vec('minute')
    v_second = get_vec('second')

    if isinstance(roll_dst, str):
        dst_repeated = roll_dst
        dst_skipped = roll_dst
    elif isinstance(roll_dst, (list, np.ndarray)):
        dst_repeated = roll_dst[0]
        dst_skipped = roll_dst[1] if len(roll_dst) > 1 else roll_dst[0]
    else:
        dst_repeated = "post"
        dst_skipped = "post"

    results = []
    for i in range(len(t_series)):
        dt_val = t_series.iloc[i]
        if pd.isna(dt_val):
            results.append(np.nan)
            continue

        curr = pd.Timestamp(dt_val)
        if curr.tz is None:
            curr = curr.tz_localize(tz)
        else:
            curr = curr.astimezone(tz)

        orig_h, orig_m, orig_s, orig_ms = curr.hour, curr.minute, curr.second, curr.microsecond

        y_add = v_year[i] if len(v_year) > 1 else v_year[0]
        m_add = v_month[i] if len(v_month) > 1 else v_month[0]

        # Civil arithmetic: logic exactly matching C++ update.cpp
        res_naive = curr.replace(tzinfo=None)

        # Year addition
        res_naive += relativedelta(years=int(y_add))

        # Month addition
        if m_add != 0:
            target_month = (res_naive.month - 1 + int(m_add)) % 12 + 1
            target_year = res_naive.year + (res_naive.month - 1 + int(m_add)) // 12

            try:
                # Check if the original day exists in the target month
                res_naive = res_naive.replace(year=target_year, month=target_month, day=res_naive.day)
                month_rolled = False
            except ValueError:
                # Month rolling kicks in
                month_rolled = True
                # Find last day of target month
                last_day_of_target = (datetime(target_year, target_month, 1) + relativedelta(months=1)) - timedelta(days=1)

                if roll_month == "preday":
                    res_naive = last_day_of_target
                elif roll_month == "postday":
                    res_naive = last_day_of_target + timedelta(days=1)
                elif roll_month == "boundary":
                    res_naive = last_day_of_target + timedelta(days=1)
                elif roll_month == "full":
                    # In C++ "full" means we let the overflow pass naturally
                    res_naive = datetime(target_year, target_month, 1) + timedelta(days=res_naive.day - 1)
                elif roll_month == "NA":
                    results.append(np.nan)
                    continue
                else: # NAym
                    res_naive = last_day_of_target
        else:
            month_rolled = False

        hms_disabled = (roll_month == "boundary" and month_rolled)

        # Week and Day addition
        w_add = v_week[i] if len(v_week) > 1 else v_week[0]
        d_add = v_day[i] if len(v_day) > 1 else v_day[0]
        res_naive = res_naive + timedelta(weeks=int(w_add), days=int(d_add))

        # HMS addition
        if not hms_disabled:
            res_naive = res_naive.replace(hour=orig_h, minute=orig_m, second=orig_s, microsecond=orig_ms)
        else:
            res_naive = res_naive.replace(hour=0, minute=0, second=0, microsecond=0)

        h_add = v_hour[i] if len(v_hour) > 1 else v_hour[0]
        m_add_hms = v_minute[i] if len(v_minute) > 1 else v_minute[0]
        s_add = v_second[i] if len(v_second) > 1 else v_second[0]
        res_naive = res_naive + timedelta(hours=int(h_add), minutes=int(m_add_hms), seconds=float(s_add))

        # DST Resolution (fold)
        t_fold0 = res_naive.replace(tzinfo=tz).replace(fold=0)
        t_fold1 = res_naive.replace(tzinfo=tz).replace(fold=1)

        if t_fold0.timestamp() == t_fold1.timestamp():
            final_t = t_fold0
        else:
            final_t = t_fold1 if dst_repeated == "post" else t_fold0

        results.append(final_t)

    if len(results) == 0:
        return np.array([])

    is_date_input = False
    if len(t_series) > 0:
        first_val = t_series.iloc[0]
        if isinstance(first_val, date) and not isinstance(first_val, datetime):
            is_date_input = True

    hms_provided = any(periods_dict.get(k) is not None for k in ['hour', 'minute', 'second'])

    if is_date_input and not hms_provided:
        return np.array([x.date() if pd.notna(x) else np.nan for x in results], dtype=object)

    return np.array(results, dtype=object)
